GIT_MODEL = ("parents = {'A': [], 'B': ['A'], 'C': ['B'], 'D': ['B'], 'E': ['D'], 'M': ['C', 'E']}\nbranches = {'main': 'M', 'feature': 'E'}\n\n"
             "def ancestors(c):\n    seen, stack = set(), [c]\n    while stack:\n        x = stack.pop()\n        if x not in seen:\n            seen.add(x)\n            stack.extend(parents[x])\n    return seen\n\n"
             "print('M-нің тарихы:', sorted(ancestors('M')))\nprint('C мен E-нің ортақ ата-бабалары:', sorted(ancestors('C') & ancestors('E')))\n"
             "print('feature main-ге енген бе:', branches['feature'] in ancestors(branches['main']))")

