PIPE_IMPL = ("def parse(text):\n    return [(n.strip(), int(s)) for n, s in (l.split(',') for l in text.strip().splitlines())]\n\n"
             "def validate(rows):\n    return [(n, s) for n, s in rows if 0 <= s <= 100]\n\n"
             "def summarize(rows):\n    if not rows:\n        return {'count': 0, 'mean': 0.0}\n    return {'count': len(rows), 'mean': round(sum(s for _, s in rows) / len(rows), 1)}\n\n"
             "def run(text):\n    return summarize(validate(parse(text)))")

